from collections import Counter

def get_block_features(grid, br, bc):
    sr, sc = br*3, bc*3
    corners = [grid[sr][sc], grid[sr][sc+2], grid[sr+2][sc], grid[sr+2][sc+2]]
    edges = [grid[sr][sc+1], grid[sr+2][sc+1], grid[sr+1][sc], grid[sr+1][sc+2]]
    center = grid[sr+1][sc+1]
    return corners, edges, center, Counter(corners+edges+[center])

def transform(grid):
    H, W = len(grid), len(grid[0])
    out_H, out_W = H//3, W//3
    result = [[0]*out_W for _ in range(out_H)]

    for br in range(out_H):
        for bc in range(out_W):
            _, _, _, all_c = get_block_features(grid, br, bc)
            result[br][bc] = all_c.most_common(1)[0][0]

    return result

