def count_adjacent_pairs(positions):
    """Count how many pairs of positions are adjacent (share an edge)"""
    pairs = 0
    sorted_pos = sorted(positions)
    for i in range(len(sorted_pos)):
        for j in range(i+1, len(sorted_pos)):
            r1, c1 = sorted_pos[i]
            r2, c2 = sorted_pos[j]
            # Adjacent if share an edge (Hamming distance = 1)
            dr = abs(r1 - r2)
            dc = abs(c1 - c2)
            if (dr == 1 and dc == 0) or (dr == 0 and dc == 1):
                pairs += 1
    return pairs

def count_chain_size(positions):
    """Find the longest chain of connected positions"""
    if len(positions) <= 1:
        return len(positions)

    # Build adjacency graph
    sorted_pos = sorted(positions)
    neighbors = {pos: [] for pos in sorted_pos}
    for i in range(len(sorted_pos)):
        for j in range(i+1, len(sorted_pos)):
            pos1 = sorted_pos[i]
            pos2 = sorted_pos[j]
            dr = abs(pos1[0] - pos2[0])
            dc = abs(pos1[1] - pos2[1])
            if (dr == 1 and dc == 0) or (dr == 0 and dc == 1):
                neighbors[pos1].append(pos2)
                neighbors[pos2].append(pos1)

    # Find longest path
    visited = set()
    max_path = 0

    def dfs(pos, depth, visited):
        nonlocal max_path
        max_path = max(max_path, depth)
        for neighbor in neighbors.get(pos, []):
            if neighbor not in visited:
                visited.add(neighbor)
                dfs(neighbor, depth + 1, visited)
                visited.remove(neighbor)

    for pos in sorted_pos:
        dfs(pos, 1, {pos})

    return max_path

